@Component("cartItem-handler")
@ProcessingGroup("cartItem-processing-group")
public class CartItemEventHandler {
	
	// core constructor
	CartItemEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateCartItemEvent
     */
    @EventHandler
    public void handle( CreateCartItemEvent event) {
        entityManager.persist(new CartItem(event.getCartItemId(), event.getQuantity(), event.getUnitPrice(), event.getTotalPrice(), event.getCart(), event.getVariant(), event.getAppliedPromotions()));
    }

    /*
     * @param	event UpdateCartItemEvent
     */
    @EventHandler
    public CartItem handle( UpdateCartItemEvent event) {
    	entityManager.merge(new CartItem(event.getCartItemId(), event.getQuantity(), event.getUnitPrice(), event.getTotalPrice(), event.getCart(), event.getVariant(), event.getAppliedPromotions()));
    }
    
    /*
     * @param	event DeleteCartItemEvent
     */
    @EventHandler
    public void on( DeleteCartItemEvent event) {
    	CartItem entity = new CartItem();
   
    	// ------------------------------------------
    	// apply the CartItemId
    	// ------------------------------------------
    	entity.setCartItemId( event.getCartItemId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final CartItemRepository cartItemEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(CartItemEventHandler.class.getName());

}
